package com.example.techfix.adapters;
import android.content.Intent;import android.net.Uri;import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.TextView;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.example.techfix.R;import com.example.techfix.models.Branch;import java.util.List;import java.util.Locale;import java.util.Map;
public class BranchAdapter extends RecyclerView.Adapter<BranchAdapter.Holder>{private final List<Branch> items;private final Map<Integer,List<String>> techs;public BranchAdapter(List<Branch> i,Map<Integer,List<String>> t){items=i;techs=t;}@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int v){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_branch,p,false));}public void onBindViewHolder(@NonNull Holder h,int i){Branch b=items.get(i);h.name.setText(b.getLocationName());h.coords.setText(String.format(Locale.getDefault(),"%s\nCoordinates: %.6f, %.6f",b.getAddress(),b.getLatitude(),b.getLongitude()));List<String> names=techs.get(b.getId());h.technicians.setText(names==null||names.isEmpty()?"No active technicians":"Active technicians: "+android.text.TextUtils.join(", ",names));h.itemView.setOnClickListener(v->{Intent in=new Intent(Intent.ACTION_VIEW, Uri.parse("geo:"+b.getLatitude()+","+b.getLongitude()+"?q="+Uri.encode(b.getLocationName())));v.getContext().startActivity(in);});}public int getItemCount(){return items.size();}static class Holder extends RecyclerView.ViewHolder{TextView name,coords,technicians;Holder(View v){super(v);name=v.findViewById(R.id.tvBranchName);coords=v.findViewById(R.id.tvBranchCoordinates);technicians=v.findViewById(R.id.tvBranchTechnicians);}}}
